import{_ as r,C as o,o as i,c as a,ag as d,E as n}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Version model","description":"Four independent version streams define the Takoform compatibility boundary.","frontmatter":{"title":"Version model","description":"Four independent version streams define the Takoform compatibility boundary."},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),s={name:"docs/versions.md"};function c(l,e,h,m,p,f){const t=o("StatusNote");return i(),a("div",null,[e[0]||(e[0]=d('<h1 id="version-model" tabindex="-1">Version model <a class="header-anchor" href="#version-model" aria-label="Permalink to &quot;Version model&quot;">​</a></h1><p>Takoform has exactly four current version streams. The first two describe domain compatibility; the latter two are independent software releases.</p><table tabindex="0"><thead><tr><th>Stream</th><th>Current form</th><th>Owner and meaning</th></tr></thead><tbody><tr><td>Host API</td><td><code>forms.takoform.com/v1</code></td><td>The literal discovery and operation lane. Compatible changes stay inside this lane; there is no <code>/v1.1</code> route.</td></tr><tr><td>Form</td><td>Each Form&#39;s <code>definitionVersion</code></td><td>The exact service shape and lifecycle contract. A family is versionless; each Form carries its own definition version.</td></tr><tr><td>Core library</td><td><code>v1.1.0</code></td><td>The independently released Core module/library. Its SemVer does not set a Host API or Provider version.</td></tr><tr><td>Provider</td><td><code>3.0.0</code></td><td>This repository&#39;s Registry-published typed mapping. Its SemVer does not publish a Form or host capability.</td></tr></tbody></table><h2 id="what-is-not-a-version-stream" tabindex="-1">What is not a version stream <a class="header-anchor" href="#what-is-not-a-version-stream" aria-label="Permalink to &quot;What is not a version stream&quot;">​</a></h2><p>The Specification 1.1 receipt is a one-time historical snapshot of normative evidence. It is not a current release train and does not create a Host API lane. The withdrawn Specification 1.0 identity is retained only in history.</p><p>Form Package envelopes, schema <code>$id</code> values, content digests, record formats, family labels, and Provider descriptors identify artifacts or publication state. They do not add a fifth stream.</p><h2 id="read-a-form-identity" tabindex="-1">Read a Form identity <a class="header-anchor" href="#read-a-form-identity" aria-label="Permalink to &quot;Read a Form identity&quot;">​</a></h2><p>When a host advertises a Form, read the complete FormRef rather than a package or Provider label. Its <code>formId</code> selects the service shape and its <code>definitionVersion</code> selects that Form&#39;s contract revision. A content digest then identifies the exact bytes that were received. A family label groups related Forms for discovery but remains versionless.</p><p>The Provider compiles a typed surface for the FormRefs it supports. It does not provide a generic carrier for an unknown Form, and a Provider release does not silently upgrade a Form definition.</p><h2 id="provider-release-history" tabindex="-1">Provider release history <a class="header-anchor" href="#provider-release-history" aria-label="Permalink to &quot;Provider release history&quot;">​</a></h2><p>The following are immutable distribution records, not additional current streams:</p><table tabindex="0"><thead><tr><th>Provider release</th><th>Historical role</th></tr></thead><tbody><tr><td><code>3.0.0</code></td><td>Current Registry-published typed mapping for the current 31 Experimental Forms.</td></tr><tr><td><code>2.1.1</code></td><td>Retained compatibility client for the historical Host API v1beta1 lane.</td></tr><tr><td><code>2.0.0</code></td><td>Retained client for the withdrawn v1alpha2 epoch.</td></tr><tr><td><code>1.0.3</code></td><td>Retained Legacy client for the withdrawn v1alpha1 epoch.</td></tr></tbody></table><p>Existing state that depends on a withdrawn epoch remains pinned to its exact Provider release. Follow the <a href="/release/migrations/v2-to-v3.html">v2 to v3 migration boundary</a> when moving that state; there is no automatic migration.</p><h2 id="version-checks-in-practice" tabindex="-1">Version checks in practice <a class="header-anchor" href="#version-checks-in-practice" aria-label="Permalink to &quot;Version checks in practice&quot;">​</a></h2><ol><li>Confirm the host&#39;s literal Host Support Profile and <code>forms.takoform.com/v1</code> endpoint.</li><li>Confirm the Form&#39;s <code>formId</code> and <code>definitionVersion</code> before writing its fields.</li><li>Pin the Core library SemVer used by the host integration.</li><li>Pin the Provider SemVer in Terraform or OpenTofu and inspect the plan.</li></ol><p>The <a href="/docs/reference-landing.html">reference landing page</a> links each current resource. The <a href="/docs/history.html">history page</a> explains the retained Specification evidence and old URLs.</p>',16)),n(t)])}const y=r(s,[["render",c]]);export{u as __pageData,y as default};
